# Today's date (assumed as July 4, 2025)
today = datetime.today()

# Function to calculate the date from "X days ago"
def get_date(days_ago):
    if days_ago == "Today":
        return today
    else:
        days = int(days_ago.split()[0])  # Extract number of days
        return today - timedelta(days=days)


# Parse the HTML with BeautifulSoup
soup = BeautifulSoup(html_code, 'html.parser')


print(soup.find_all('g'))  # Print the title of the page
# Find all elements with the class "ke9kZe-LkdAo-RbRzK-JNdkSc pKrx3d"
data_points = soup.find_all('g', role='img')
print(data_points)


# Create a dictionary to store the price history
price_history = {}

# Extract dates and prices from each data point
for point in data_points:

    print(2)
    label = point.get('aria-label')  # Get the aria-label attribute
    if label:
        date_part, price_part = label.split(' - ')  # Split into date and price
        # convert to number of days ago
        if date_part == 'Today':
            date = 0
        else:
            date = int(date_part.split()[0])
        date = date + 36
        price = int(price_part.replace('€', ''))  # Remove € and convert to integer
        price_history[date] = price

# save into a csv file 
data = pd.DataFrame(list(price_history.items()), columns=['Date', 'Price'])
data.to_csv('kun_mad.csv', index=False)